llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "BMS-275183, a complex lipophilic diterpenoid taxane with poor aqueous solubility, has a 24% mean absolute oral bioavailability in humans, demonstrating that a polycyclic natural product can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Zidovudine has an absolute oral bioavailability of 54–74% in humans, supporting high F for a small molecule subject to first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Didanosine absolute oral bioavailability in humans is 30–54%, above the 20% threshold despite acid lability and variable absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Emtricitabine has an absolute oral bioavailability of 93% in humans, a clear high-F example.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Zalcitabine absolute oral bioavailability is 70–80% in patients with AIDS, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Paliperidone has an absolute oral bioavailability of 28% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Thiocolchicoside oral solution bioavailability is 27 ± 7%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Ursodeoxycholic acid systemic availability is 50% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Amphotericin B has negligible oral bioavailability due to its large size, poor permeability, and low solubility; these features are not shared by the much smaller, more lipophilic triptolide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer experimental evidence from diverse small-molecule drugs reports absolute oral bioavailability above 20%, including complex lipophilic natural products such as BMS-275183 (24%). The only strong low-F evidence, amphotericin B, is mechanistically tied to macromolecular size and extreme polarity, which triptolide does not share. Therefore, triptolide is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for triptolide itself is provided.",
    "Uncertainty remains about triptolide's acid stability, P-glycoprotein efflux, and first-pass metabolism.",
    "Amphotericin B low-F evidence is only weakly mechanistically transferable despite a high assay-transfer score."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

